// Everything the app needs to talk to the MedTrace contract, in one place.
// Pages import helpers from here instead of touching ethers directly.
import { BrowserProvider, Contract, JsonRpcProvider, ZeroHash, id as keccakId } from "ethers";

// contract.json is generated by `npm run sync-contract` and git-ignored.
// When it's missing the app still loads and shows a "not configured" screen.
const modules = import.meta.glob("../contract.json", { eager: true });
export const CONFIG = modules["../contract.json"]?.default ?? null;

export const NETWORKS = {
  31337: { name: "local Hardhat network", rpc: "http://127.0.0.1:8545", hex: "0x7a69", currency: "ETH" },
  80002: { name: "Polygon Amoy test network", rpc: "https://polygon-amoy-bor-rpc.publicnode.com", hex: "0x13882", currency: "POL", explorer: "https://amoy.polygonscan.com" },
};

// Role identifiers exactly as the contract computes them (keccak256 of the name).
export const ROLE_IDS = {
  admin: ZeroHash,
  manufacturer: keccakId("MANUFACTURER_ROLE"),
  distributor: keccakId("DISTRIBUTOR_ROLE"),
  pharmacy: keccakId("PHARMACY_ROLE"),
  regulator: keccakId("REGULATOR_ROLE"),
  sensor: keccakId("SENSOR_ROLE"),
};
export const ROLE_BY_ID = Object.fromEntries(Object.entries(ROLE_IDS).map(([k, v]) => [v.toLowerCase(), k]));

// Plain-language labels and icons. The UI never shows the raw role constant.
export const ROLE_LABELS = { admin: "Network operator", manufacturer: "Factory", distributor: "Distributor", pharmacy: "Pharmacy", regulator: "Regulator", sensor: "Temperature sensor", patient: "Patient" };
export const ROLE_ICONS = { admin: "admin_panel_settings", manufacturer: "factory", distributor: "local_shipping", pharmacy: "local_pharmacy", regulator: "gavel", sensor: "sensors", patient: "favorite" };
// One colour per role, used for tiles, stations and Pip.
export const ROLE_COLORS = { admin: "#5B4CF5", manufacturer: "#FF8A3D", distributor: "#3DA5FF", pharmacy: "#22C08F", regulator: "#8B5CF6", sensor: "#FFB020", patient: "#FF6FA8" };
export const ROLE_HOME = { admin: "/admin", manufacturer: "/factory", distributor: "/distributor", pharmacy: "/pharmacy", regulator: "/regulator", sensor: "/" };

// enum BatchStatus { Created, InTransit, Received, Dispensed, Recalled }
export const STATUS = ["Created", "In transit", "Received", "Dispensed", "Recalled"];
// enum ActionType, same order as the contract.
export const ACTION = { Registered: 0, CustodyTransferred: 1, ReceiptConfirmed: 2, Dispensed: 3, DocumentAttached: 4, TemperatureAlert: 5, Certified: 6, Recalled: 7 };
export const ACTION_LABELS = ["Registered at the factory", "Handed off", "Delivery accepted", "Dispensed to patient", "Document attached", "Temperature alert", "Certified by the regulator", "Recalled by the regulator"];
export const DOC_LABELS = ["Certificate of analysis", "Temperature log", "Shipping record", "Regulator certificate", "Other document"];

// Timeline state derived from a batch. "alert" wins over received/created so the breach is visible.
export function timelineState(b) {
  if (b.status === 4) return "recalled";
  if (b.status === 3) return "dispensed";
  if (b.temperatureBreached) return "alert";
  return ["created", "transit", "received"][b.status] || "received";
}
export const STATE_CHIP = {
  created: { text: "Created", icon: "add_circle", tone: "neutral" },
  transit: { text: "In transit", icon: "hourglass_top", tone: "wait" },
  received: { text: "Received", icon: "check_circle", tone: "safe" },
  dispensed: { text: "Dispensed", icon: "lock", tone: "safe" },
  recalled: { text: "Recalled", icon: "block", tone: "danger" },
  alert: { text: "Temperature alert", icon: "thermostat", tone: "danger" },
};

export function readProvider() {
  if (!CONFIG) return null;
  if (window.ethereum) return new BrowserProvider(window.ethereum);
  return new JsonRpcProvider(NETWORKS[CONFIG.chainId]?.rpc ?? NETWORKS[31337].rpc);
}
export function readContract() {
  const p = readProvider();
  return p ? new Contract(CONFIG.address, CONFIG.abi, p) : null;
}
export function writeContract(signer) {
  return new Contract(CONFIG.address, CONFIG.abi, signer);
}

// Which single role does this account have? Checks the roles in order.
export async function detectRole(contract, account) {
  for (const key of ["admin", "manufacturer", "distributor", "pharmacy", "regulator", "sensor"]) {
    if (await contract.hasRole(ROLE_IDS[key], account)) return key;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Event reading
// Public Amoy endpoints refuse event searches wider than 10,000 blocks, so events
// are read in chunks, starting at the block the contract was deployed in
// (CONFIG.deployBlock, written by sync-contract). Logs always go through the
// network's own endpoint, not the wallet's, so the limit is a known one.
// Results are cached per event: later calls only read the blocks added since.
// ---------------------------------------------------------------------------
const LOG_CHUNK = 9000;
const LOG_PARALLEL = 4;
let logContract = null;
const logCache = new Map(); // event name -> { next, logs, pending }

function eventReader() {
  if (!logContract) {
    const rpc = NETWORKS[CONFIG.chainId]?.rpc ?? NETWORKS[31337].rpc;
    const provider = new JsonRpcProvider(rpc, CONFIG.chainId ?? undefined, CONFIG.chainId ? { staticNetwork: true } : undefined);
    logContract = new Contract(CONFIG.address, CONFIG.abi, provider);
  }
  return logContract;
}

async function scanNewBlocks(eventName, entry) {
  const contract = eventReader();
  const head = await contract.runner.getBlockNumber();
  if (head < entry.next - 1) { // the chain was reset (local node restarted)
    entry.next = CONFIG.deployBlock ?? 0;
    entry.logs = [];
  }
  const ranges = [];
  for (let from = entry.next; from <= head; from += LOG_CHUNK) ranges.push([from, Math.min(from + LOG_CHUNK - 1, head)]);
  const results = new Array(ranges.length);
  let cursor = 0;
  const worker = async () => {
    while (cursor < ranges.length) {
      const k = cursor++;
      results[k] = await contract.queryFilter(contract.filters[eventName](), ...ranges[k]);
    }
  };
  await Promise.all(Array.from({ length: Math.min(LOG_PARALLEL, ranges.length) }, worker));
  entry.logs = entry.logs.concat(results.flat());
  entry.next = head + 1;
  return entry.logs;
}

/** Every `eventName` log since deployment, oldest first. Throws if the endpoint fails. */
export function readEvents(eventName) {
  let entry = logCache.get(eventName);
  if (!entry) {
    entry = { next: CONFIG.deployBlock ?? 0, logs: [], pending: Promise.resolve() };
    logCache.set(eventName, entry);
  }
  // Chain calls for the same event so two pages loading at once don't scan twice.
  const run = entry.pending.catch(() => {}).then(() => scanNewBlocks(eventName, entry));
  entry.pending = run;
  return run;
}

const byChainOrder = (a, b) => a.blockNumber - b.blockNumber || a.index - b.index;

// Everyone the operator has onboarded: { addressLower: { address, role, name } }.
// Read from ParticipantRegistered/Removed events; falls back to an empty roster if the endpoint fails.
export async function loadParticipants() {
  const roster = {};
  try {
    const [added, removed] = await Promise.all([readEvents("ParticipantRegistered"), readEvents("ParticipantRemoved")]);
    for (const l of [...added, ...removed].sort(byChainOrder)) {
      const key = l.args.account.toLowerCase();
      if (l.fragment.name === "ParticipantRemoved") delete roster[key];
      else roster[key] = { address: l.args.account, role: ROLE_BY_ID[l.args.role.toLowerCase()], name: l.args.name };
    }
  } catch (e) {
    console.warn("Could not read the participant list from events:", e?.shortMessage || e?.message);
  }
  return roster;
}

// Temperature readings for a batch, from TempAlert events (the reading isn't stored in history).
export async function loadTempAlerts(batchId) {
  try {
    const logs = await readEvents("TempAlert");
    return logs
      .filter((l) => Number(l.args.batchId) === Number(batchId))
      .map((l) => ({ readingTenthsC: Number(l.args.readingTenthsC), logCid: l.args.logCid }));
  } catch (e) {
    console.warn("Could not read temperature alerts from events:", e?.shortMessage || e?.message);
    return [];
  }
}

// Loads every batch (ids start at 1). Fine for a demo-sized ledger.
export async function loadAllBatches(contract) {
  const total = Number(await contract.totalBatches());
  const ids = Array.from({ length: total }, (_, i) => i + 1);
  const raw = await Promise.all(ids.map((i) => contract.getBatch(i)));
  return raw.map(normalizeBatch);
}

export function normalizeBatch(b) {
  return {
    id: Number(b.id), productName: b.productName, lotNumber: b.lotNumber,
    manufacturer: b.manufacturer, currentHolder: b.currentHolder, pendingHolder: b.pendingHolder,
    manufactureDate: Number(b.manufactureDate), expiryDate: Number(b.expiryDate),
    minTempTenthsC: Number(b.minTempTenthsC), maxTempTenthsC: Number(b.maxTempTenthsC),
    status: Number(b.status), certified: Boolean(b.certified), temperatureBreached: Boolean(b.temperatureBreached),
  };
}
export function normalizeHistory(entries) {
  return entries.map((e) => ({ action: Number(e.action), actor: e.actor, status: Number(e.status), timestamp: Number(e.timestamp), details: e.details }));
}

export const isZero = (a) => !a || /^0x0{40}$/i.test(a);
export const shortAddr = (a) => (a ? `${a.slice(0, 6)}…${a.slice(-4)}` : "");
export const tempC = (tenths) => `${(tenths / 10).toFixed(1)} °C`;
export const rangeC = (lo, hi) => `${(lo / 10).toFixed(1)}–${(hi / 10).toFixed(1)} °C`;
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
// "5 Nov, 14:02" style, as in the design.
export const when = (unix) => { if (!unix) return ""; const d = new Date(unix * 1000); return `${d.getDate()} ${MONTHS[d.getMonth()]}, ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`; };
// "31 Mar 2028"
export const dateOf = (unix) => { if (!unix) return ""; const d = new Date(unix * 1000); return `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`; };

// Turns a revert into a sentence a person can act on.
export function friendlyError(err) {
  const msg = err?.shortMessage || err?.reason || err?.message || String(err);
  if (/user rejected|ACTION_REJECTED|rejected the request/i.test(msg)) return "Your wallet app declined the request.";
  const m = msg.match(/MedTrace: ([^"']+)/);
  if (m) return `The record refused it: ${m[1]}.`;
  if (/AccessControl/i.test(msg)) return "This account isn't allowed to do that.";
  if (/insufficient funds/i.test(msg)) return "This account has no test funds to pay for the transaction.";
  if (/could not coalesce|timeout|network/i.test(msg)) return "The blockchain didn't confirm in time.";
  return msg.length > 140 ? msg.slice(0, 137) + "…" : msg;
}

// A friendly icon + colour for a product, picked from its name (stable per name).
const PRODUCT_PALETTE = ["#5B4CF5", "#3DA5FF", "#FF6FA8", "#22C08F", "#FF8A3D"];
export function productLook(name = "") {
  const n = name.toLowerCase();
  const icon = /insulin|vaccin|inject/.test(n) ? "vaccines" : /inhal/.test(n) ? "air" : /syrup|liquid|suspension/.test(n) ? "medication_liquid" : /capsule|amox/.test(n) ? "pill" : "medication";
  let h = 0;
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return { icon, color: PRODUCT_PALETTE[h % PRODUCT_PALETTE.length] };
}
export const shortName = (s = "") => s.split(" ")[0] || s;
// "5 Nov"
export const dayOf = (unix) => { if (!unix) return ""; const d = new Date(unix * 1000); return `${d.getDate()} ${MONTHS[d.getMonth()]}`; };
// "Mar 2028"
export const monthYear = (unix) => { if (!unix) return ""; const d = new Date(unix * 1000); return `${MONTHS[d.getMonth()]} ${d.getFullYear()}`; };

// ---------------------------------------------------------------------------
// IPFS documents. Only CIDs are stored on-chain; files open through a public gateway.
// ---------------------------------------------------------------------------
export const IPFS_GATEWAY = "https://gateway.pinata.cloud/ipfs/";
// CIDv0 ("Qm" + 44 base58 chars) or CIDv1 in base32 ("b" + lowercase letters/digits 2-7).
export const isCid = (s) => typeof s === "string" && (/^Qm[1-9A-HJ-NP-Za-km-z]{44}$/.test(s.trim()) || /^b[a-z2-7]{50,}$/.test(s.trim()));
export const ipfsUrl = (cid) => `${IPFS_GATEWAY}${cid.trim()}`;

// Documents linked to a batch: [{ docType, label, cid, uploadedBy, timestamp }].
export async function loadDocuments(contract, batchId) {
  const docs = await contract.getDocuments(batchId);
  return docs.map((d) => ({
    docType: Number(d.docType), label: DOC_LABELS[Number(d.docType)] || "Document",
    cid: d.cid, uploadedBy: d.uploadedBy, timestamp: Number(d.timestamp),
  }));
}
